Product: {{ $json.productName }} | Requester: {{ $json.requesterType }} ({{ $json.requesterName }})
Question: {{ $json.question }}
Reasoning: {{ $json.classificationReasoning }}
An urgent safety case has been opened for immediate follow-up.

parameters.jsCode:
const upstream = $('JS - Parse Classification Output').first().json;
const kbResponse = $input.first().json;
const matches = kbResponse.results || kbResponse.matches || kbResponse.sources || [];
const highRelevanceMatches = matches.filter(m => (m.relevanceScore ?? m.score ?? 0) >= 0.6);

return [{
  json: {
    ...upstream,
    retrievedSources: matches,
    hasSufficientCoverage: highRelevanceMatches.length > 0
  }
}];

parameters.text:
=You are a medical information specialist drafting a response using ONLY approved company sources.

Requester type: {{ $json.requesterType }}
Product: {{ $json.productName }}
Question: {{ $json.question }}

Approved sources retrieved for this question:
{{ JSON.stringify($json.retrievedSources, null, 2) }}

Draft a response using ONLY information contained in the sources above. Cite which source(s) support each part of your answer. Do not add any information, dosing guidance, or clinical judgment beyond what the sources explicitly state. If the sources do not fully and directly answer the question, say so plainly and set canFullyAnswer to false rather than filling gaps yourself.

Return ONLY a JSON object (no markdown fences, no commentary) with keys: draftAnswer (string, empty if canFullyAnswer is false), citedSources (array of strings, source titles or IDs used), canFullyAnswer (boolean), draftReasoning (one short sentence explaining the canFullyAnswer decision).

parameters.jsCode:
const upstream = $('JS - Evaluate Knowledge Base Coverage').first().json;
const response = $input.first().json;

let parsed = {
  draftAnswer: '',
  citedSources: [],
  canFullyAnswer: false,
  draftReasoning: 'AI drafting unavailable this cycle; defaulted to escalation as a safety default.'
};
try {
  const raw = String(response.output || response.text || response.response || '{}').replace(/```json|```/g, '').trim();
  const result = JSON.parse(raw);
  parsed = { ...parsed, ...result };
} catch (e) {
  // keep safe default above
}

return [{
  json: {
    ...upstream,
    draftAnswer: parsed.draftAnswer,
    citedSources: parsed.citedSources,
    canFullyAnswer: parsed.canFullyAnswer,
    draftReasoning: parsed.draftReasoning
  }
}];

const item = $input.first().json;
let routingMap = {};
try { routingMap = JSON.parse(item.teamRoutingMapJson || '{}'); } catch (e) { routingMap = {}; }

const routing = routingMap[item.topicCategory] || { team: 'Medical Information - General', channel: item.miTeamSlackChannelDefault || '#medical-information' };

const canAutoAnswer = item.complexity === 'Standard'
  && item.urgency === 'Routine'
  && item.canFullyAnswer === true
  && item.hasSufficientCoverage === true;

return [{
  json: {
    ...item,
    routingTeam: routing.team,
    routingSlackChannel: routing.channel,
    canAutoAnswer
  }
}];

